import os.log
import PassKit
import UIKit

/// UI-extension view controller for Wallet-initiated authentication
/// (P0-2 §4.7, UI extension half). Apple's two-extension architecture
/// (DEV-4.0 §10) pairs this UI extension with the non-UI
/// `PKIssuerProvisioningExtensionHandler` — when `status()` reports
/// `requiresAuthentication = true`, Wallet invokes this class inside its own
/// UI rather than redirecting to the host app.
///
/// Consumer apps subclass this with a thin brand subclass auto-generated by
/// the config plugin:
///
/// ```swift
/// import react_native_wallet_extension_auth
/// @objc(DarbWalletAuthExtension)
/// class DarbWalletAuthExtension: WalletAuthorizationProvidingViewController {}
/// ```
///
/// **Iteration 2: inline phone + OTP sign-in.** Mirrors the host RN app's
/// `darbpay-mobile/hooks/use-login-flow.ts` flow + UI: the same phone-code
/// sign-in (`signIn.create` → `prepareFirstFactor` → `attemptFirstFactor`),
/// the same `mapClerkError` mapping for human-readable inline errors, the
/// same 90s resend cooldown, the same auto-submit on a 6-digit OTP. Talks to
/// Clerk's Frontend API directly because the extension can't link the RN
/// Clerk SDK. On success, writes a JWT-template token to `SharedKeychain` and
/// reports `.authorized` so Wallet re-polls the provisioning extension.
@available(iOS 14.0, *)
@objc open class WalletAuthorizationProvidingViewController: UIViewController, PKIssuerProvisioningExtensionAuthorizationProviding {

  // `PKIssuerProvisioningExtensionAuthorizationProviding` requirement. Wallet
  // assigns this before presenting the VC; we invoke it exactly once.
  public var completionHandler: ((PKIssuerProvisioningExtensionAuthorizationResult) -> Void)?

  private static let log = OSLog(
    subsystem: Bundle.main.bundleIdentifier ?? "react-native-wallet-extension-auth",
    category: "auth-ui"
  )

  // MARK: - State (mirrors useLoginFlow)

  private enum Phase { case phone, otp }
  private var phase: Phase = .phone
  private var selectedCountry: Country = LOGIN_COUNTRIES[0]
  private var phoneDigits: String = ""
  private var otpValue: String = ""
  private var errorMessage: String?
  private var isSubmitting: Bool = false
  private var cooldown: Int = 0
  private var prepared: ClerkFrontendClient.PreparedSignIn?
  private var didComplete = false

  private let client = ClerkFrontendClient()
  private var cooldownTimer: Timer?

  // MARK: - Views

  // Heading icons — logo for phone phase, hidden in OTP phase (logo also
  // appears at the top of OTP heading block separately).
  private let phoneLogoView = DarbLogoView()
  private let otpLogoView = DarbLogoView()
  private let languagePill = LanguagePill()
  private let backButton: UIButton = {
    let b = UIButton(type: .system)
    let cfg = UIImage.SymbolConfiguration(pointSize: 18, weight: .semibold)
    b.setImage(UIImage(systemName: "chevron.left", withConfiguration: cfg), for: .normal)
    b.tintColor = DarbColors.foreground
    return b
  }()

  private let phoneTitle: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 21.5, weight: .bold)
    l.textColor = DarbColors.foreground
    l.numberOfLines = 0
    l.textAlignment = .left
    l.text = LoginCopy.phoneScreenTitle
    return l
  }()

  private let phoneSubtitle: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 16, weight: .regular)
    l.textColor = DarbColors.mutedForeground
    l.numberOfLines = 0
    l.textAlignment = .left
    l.text = LoginCopy.phoneScreenSubtitle
    return l
  }()

  private let otpTitle: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 21.5, weight: .bold)
    l.textColor = DarbColors.foreground
    l.numberOfLines = 0
    l.textAlignment = .center
    l.text = LoginCopy.enterVerificationCode
    return l
  }()

  private let otpSubtitle: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 16, weight: .regular)
    l.textColor = DarbColors.mutedForeground
    l.numberOfLines = 0
    l.textAlignment = .center
    l.text = LoginCopy.otpInstruction
    return l
  }()

  private let otpPhoneLabel: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 17, weight: .regular)
    l.textColor = DarbColors.mutedForeground
    l.textAlignment = .center
    return l
  }()

  private lazy var phoneInputRow = PhoneInputRow(
    onCountryTap: { [weak self] in self?.pickCountry() },
    onTextChange: { [weak self] in self?.phoneChanged() }
  )

  private lazy var otpCellsView: OtpCellsView = {
    let v = OtpCellsView(length: OTP_LENGTH)
    v.onChange = { [weak self] value in self?.otpChanged(value) }
    return v
  }()

  private lazy var primaryButton: PillButton = {
    let b = PillButton()
    b.title = LoginCopy.continueLabel
    b.addTarget(self, action: #selector(primaryTapped), for: .touchUpInside)
    return b
  }()

  private let phoneErrorLabel: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 14, weight: .regular)
    l.textColor = DarbColors.destructive
    l.numberOfLines = 0
    l.textAlignment = .left
    return l
  }()

  private let otpErrorLabel: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 14, weight: .regular)
    l.textColor = DarbColors.destructive
    l.numberOfLines = 0
    l.textAlignment = .center
    return l
  }()

  private let resendLabel: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 14, weight: .medium)
    l.textAlignment = .center
    l.numberOfLines = 1
    l.isUserInteractionEnabled = true
    return l
  }()

  private let spinner: UIActivityIndicatorView = {
    let s = UIActivityIndicatorView(style: .medium)
    s.hidesWhenStopped = true
    return s
  }()

  // Phase-grouping containers so we can toggle visibility wholesale.
  private let phoneContainer = UIView()
  private let otpContainer = UIView()

  // "Done" toolbar shared by the phone field and the hidden OTP field —
  // numberPad has no return key, so without this the keyboard can't be
  // dismissed. On the phone screen, tapping Done also submits when the entered
  // phone is the right length (matches the "complete keyboard now that
  // dismisses keyboard and submits" flow the user asked for).
  private lazy var dismissToolbar: UIToolbar = {
    let bar = UIToolbar()
    bar.barStyle = .default
    bar.sizeToFit()
    let flex = UIBarButtonItem(barButtonSystemItem: .flexibleSpace, target: nil, action: nil)
    let done = UIBarButtonItem(barButtonSystemItem: .done, target: self, action: #selector(doneTapped))
    bar.items = [flex, done]
    return bar
  }()

  // MARK: - Lifecycle

  open override func viewDidLoad() {
    super.viewDidLoad()
    view.backgroundColor = DarbColors.background

    // If no publishable key was provisioned, there's nothing this UI can do —
    // bail gracefully so Wallet falls back to "open the app".
    guard ClerkFrontendClient.isConfigured else {
      os_log("auth UI not configured (no publishable key) → canceled", log: Self.log, type: .error)
      finish(.canceled)
      return
    }

    buildLayout()
    wireGestures()

    phoneInputRow.setInputAccessoryView(dismissToolbar)
    otpCellsView.setInputAccessoryView(dismissToolbar)

    render()
  }

  open override func viewDidAppear(_ animated: Bool) {
    super.viewDidAppear(animated)
    // becomeFirstResponder() from viewDidLoad can silently no-op because the
    // view isn't in a window yet. Re-arm focus once the wallet host has
    // actually presented us.
    switch phase {
    case .phone: _ = phoneInputRow.becomeFirstResponder()
    case .otp: _ = otpCellsView.becomeFirstResponder()
    }
  }

  deinit {
    cooldownTimer?.invalidate()
  }

  // MARK: - Layout

  private func buildLayout() {
    phoneContainer.translatesAutoresizingMaskIntoConstraints = false
    otpContainer.translatesAutoresizingMaskIntoConstraints = false
    primaryButton.translatesAutoresizingMaskIntoConstraints = false
    spinner.translatesAutoresizingMaskIntoConstraints = false
    view.addSubview(phoneContainer)
    view.addSubview(otpContainer)
    view.addSubview(primaryButton)
    view.addSubview(spinner)

    let safe = view.safeAreaLayoutGuide
    NSLayoutConstraint.activate([
      phoneContainer.topAnchor.constraint(equalTo: safe.topAnchor),
      phoneContainer.leadingAnchor.constraint(equalTo: safe.leadingAnchor),
      phoneContainer.trailingAnchor.constraint(equalTo: safe.trailingAnchor),
      phoneContainer.bottomAnchor.constraint(equalTo: primaryButton.topAnchor, constant: -8),

      otpContainer.topAnchor.constraint(equalTo: safe.topAnchor),
      otpContainer.leadingAnchor.constraint(equalTo: safe.leadingAnchor),
      otpContainer.trailingAnchor.constraint(equalTo: safe.trailingAnchor),
      otpContainer.bottomAnchor.constraint(equalTo: safe.bottomAnchor),

      primaryButton.leadingAnchor.constraint(equalTo: safe.leadingAnchor, constant: 20),
      primaryButton.trailingAnchor.constraint(equalTo: safe.trailingAnchor, constant: -20),
      primaryButton.heightAnchor.constraint(equalToConstant: 56),
      // Continue button is pinned to the safe-area bottom and stays there even
      // when the keyboard is up — the user dismisses + submits via the input
      // accessory Done button.
      primaryButton.bottomAnchor.constraint(equalTo: safe.bottomAnchor, constant: -24),

      spinner.centerXAnchor.constraint(equalTo: view.centerXAnchor),
      spinner.bottomAnchor.constraint(equalTo: primaryButton.topAnchor, constant: -12),
    ])

    buildPhonePhase()
    buildOtpPhase()
  }

  private func buildPhonePhase() {
    let topBar = UIView()
    topBar.translatesAutoresizingMaskIntoConstraints = false
    languagePill.translatesAutoresizingMaskIntoConstraints = false
    topBar.addSubview(languagePill)

    phoneLogoView.translatesAutoresizingMaskIntoConstraints = false
    let logoBox = UIView()
    logoBox.translatesAutoresizingMaskIntoConstraints = false
    logoBox.addSubview(phoneLogoView)

    let headingStack = UIStackView(arrangedSubviews: [phoneTitle, phoneSubtitle])
    headingStack.axis = .vertical
    headingStack.spacing = 8
    headingStack.alignment = .fill
    headingStack.translatesAutoresizingMaskIntoConstraints = false

    let phoneInputRowWrapper = UIView()
    phoneInputRowWrapper.translatesAutoresizingMaskIntoConstraints = false
    phoneInputRow.translatesAutoresizingMaskIntoConstraints = false
    phoneInputRowWrapper.addSubview(phoneInputRow)

    phoneErrorLabel.translatesAutoresizingMaskIntoConstraints = false

    phoneContainer.addSubview(topBar)
    phoneContainer.addSubview(logoBox)
    phoneContainer.addSubview(headingStack)
    phoneContainer.addSubview(phoneInputRowWrapper)
    phoneContainer.addSubview(phoneErrorLabel)

    NSLayoutConstraint.activate([
      topBar.topAnchor.constraint(equalTo: phoneContainer.topAnchor, constant: 10),
      topBar.leadingAnchor.constraint(equalTo: phoneContainer.leadingAnchor, constant: 20),
      topBar.trailingAnchor.constraint(equalTo: phoneContainer.trailingAnchor, constant: -20),
      topBar.heightAnchor.constraint(greaterThanOrEqualToConstant: 36),

      languagePill.trailingAnchor.constraint(equalTo: topBar.trailingAnchor),
      languagePill.centerYAnchor.constraint(equalTo: topBar.centerYAnchor),
      languagePill.topAnchor.constraint(greaterThanOrEqualTo: topBar.topAnchor),
      languagePill.bottomAnchor.constraint(lessThanOrEqualTo: topBar.bottomAnchor),

      logoBox.topAnchor.constraint(equalTo: topBar.bottomAnchor, constant: 36),
      logoBox.leadingAnchor.constraint(equalTo: phoneContainer.leadingAnchor, constant: 20),
      logoBox.trailingAnchor.constraint(equalTo: phoneContainer.trailingAnchor, constant: -20),

      phoneLogoView.centerXAnchor.constraint(equalTo: logoBox.centerXAnchor),
      phoneLogoView.topAnchor.constraint(equalTo: logoBox.topAnchor),
      phoneLogoView.bottomAnchor.constraint(equalTo: logoBox.bottomAnchor),
      phoneLogoView.widthAnchor.constraint(equalToConstant: 120),
      phoneLogoView.heightAnchor.constraint(equalToConstant: 48),

      headingStack.topAnchor.constraint(equalTo: logoBox.bottomAnchor, constant: 40),
      headingStack.leadingAnchor.constraint(equalTo: phoneContainer.leadingAnchor, constant: 20),
      headingStack.trailingAnchor.constraint(equalTo: phoneContainer.trailingAnchor, constant: -20),

      phoneInputRowWrapper.topAnchor.constraint(equalTo: headingStack.bottomAnchor, constant: 28),
      phoneInputRowWrapper.leadingAnchor.constraint(equalTo: phoneContainer.leadingAnchor, constant: 20),
      phoneInputRowWrapper.trailingAnchor.constraint(equalTo: phoneContainer.trailingAnchor, constant: -20),

      phoneInputRow.topAnchor.constraint(equalTo: phoneInputRowWrapper.topAnchor),
      phoneInputRow.leadingAnchor.constraint(equalTo: phoneInputRowWrapper.leadingAnchor),
      phoneInputRow.trailingAnchor.constraint(equalTo: phoneInputRowWrapper.trailingAnchor),
      phoneInputRow.bottomAnchor.constraint(equalTo: phoneInputRowWrapper.bottomAnchor),

      phoneErrorLabel.topAnchor.constraint(equalTo: phoneInputRowWrapper.bottomAnchor, constant: 8),
      phoneErrorLabel.leadingAnchor.constraint(equalTo: phoneContainer.leadingAnchor, constant: 20),
      phoneErrorLabel.trailingAnchor.constraint(equalTo: phoneContainer.trailingAnchor, constant: -20),
      phoneErrorLabel.heightAnchor.constraint(greaterThanOrEqualToConstant: 20),
    ])
  }

  private func buildOtpPhase() {
    let topBar = UIView()
    topBar.translatesAutoresizingMaskIntoConstraints = false
    backButton.translatesAutoresizingMaskIntoConstraints = false
    topBar.addSubview(backButton)

    otpLogoView.translatesAutoresizingMaskIntoConstraints = false
    let logoBox = UIView()
    logoBox.translatesAutoresizingMaskIntoConstraints = false
    logoBox.addSubview(otpLogoView)

    let headingStack = UIStackView(arrangedSubviews: [otpTitle, otpSubtitle, otpPhoneLabel])
    headingStack.axis = .vertical
    headingStack.spacing = 8
    headingStack.alignment = .fill
    headingStack.setCustomSpacing(4, after: otpSubtitle)
    headingStack.translatesAutoresizingMaskIntoConstraints = false

    let otpRowWrapper = UIView()
    otpRowWrapper.translatesAutoresizingMaskIntoConstraints = false
    otpCellsView.translatesAutoresizingMaskIntoConstraints = false
    otpRowWrapper.addSubview(otpCellsView)

    otpErrorLabel.translatesAutoresizingMaskIntoConstraints = false
    resendLabel.translatesAutoresizingMaskIntoConstraints = false

    otpContainer.addSubview(topBar)
    otpContainer.addSubview(logoBox)
    otpContainer.addSubview(headingStack)
    otpContainer.addSubview(otpRowWrapper)
    otpContainer.addSubview(otpErrorLabel)
    otpContainer.addSubview(resendLabel)

    NSLayoutConstraint.activate([
      topBar.topAnchor.constraint(equalTo: otpContainer.topAnchor, constant: 10),
      topBar.leadingAnchor.constraint(equalTo: otpContainer.leadingAnchor, constant: 20),
      topBar.trailingAnchor.constraint(equalTo: otpContainer.trailingAnchor, constant: -20),
      topBar.heightAnchor.constraint(greaterThanOrEqualToConstant: 36),

      backButton.leadingAnchor.constraint(equalTo: topBar.leadingAnchor),
      backButton.centerYAnchor.constraint(equalTo: topBar.centerYAnchor),
      backButton.widthAnchor.constraint(equalToConstant: 28),
      backButton.heightAnchor.constraint(equalToConstant: 28),

      logoBox.topAnchor.constraint(equalTo: topBar.bottomAnchor, constant: 36),
      logoBox.leadingAnchor.constraint(equalTo: otpContainer.leadingAnchor, constant: 20),
      logoBox.trailingAnchor.constraint(equalTo: otpContainer.trailingAnchor, constant: -20),

      otpLogoView.centerXAnchor.constraint(equalTo: logoBox.centerXAnchor),
      otpLogoView.topAnchor.constraint(equalTo: logoBox.topAnchor),
      otpLogoView.bottomAnchor.constraint(equalTo: logoBox.bottomAnchor),
      otpLogoView.widthAnchor.constraint(equalToConstant: 120),
      otpLogoView.heightAnchor.constraint(equalToConstant: 48),

      headingStack.topAnchor.constraint(equalTo: logoBox.bottomAnchor, constant: 40),
      headingStack.leadingAnchor.constraint(equalTo: otpContainer.leadingAnchor, constant: 20),
      headingStack.trailingAnchor.constraint(equalTo: otpContainer.trailingAnchor, constant: -20),

      otpRowWrapper.topAnchor.constraint(equalTo: headingStack.bottomAnchor, constant: 28),
      otpRowWrapper.leadingAnchor.constraint(equalTo: otpContainer.leadingAnchor, constant: 20),
      otpRowWrapper.trailingAnchor.constraint(equalTo: otpContainer.trailingAnchor, constant: -20),

      otpCellsView.topAnchor.constraint(equalTo: otpRowWrapper.topAnchor),
      otpCellsView.centerXAnchor.constraint(equalTo: otpRowWrapper.centerXAnchor),
      otpCellsView.bottomAnchor.constraint(equalTo: otpRowWrapper.bottomAnchor),
      otpCellsView.leadingAnchor.constraint(greaterThanOrEqualTo: otpRowWrapper.leadingAnchor),
      otpCellsView.trailingAnchor.constraint(lessThanOrEqualTo: otpRowWrapper.trailingAnchor),

      otpErrorLabel.topAnchor.constraint(equalTo: otpRowWrapper.bottomAnchor, constant: 12),
      otpErrorLabel.leadingAnchor.constraint(equalTo: otpContainer.leadingAnchor, constant: 20),
      otpErrorLabel.trailingAnchor.constraint(equalTo: otpContainer.trailingAnchor, constant: -20),
      otpErrorLabel.heightAnchor.constraint(greaterThanOrEqualToConstant: 20),

      resendLabel.topAnchor.constraint(equalTo: otpErrorLabel.bottomAnchor, constant: 8),
      resendLabel.leadingAnchor.constraint(equalTo: otpContainer.leadingAnchor, constant: 20),
      resendLabel.trailingAnchor.constraint(equalTo: otpContainer.trailingAnchor, constant: -20),
    ])
  }

  private func wireGestures() {
    backButton.addTarget(self, action: #selector(backTapped), for: .touchUpInside)
    resendLabel.addGestureRecognizer(UITapGestureRecognizer(target: self, action: #selector(resendTapped)))
  }

  // MARK: - Render

  private func render() {
    switch phase {
    case .phone:
      phoneContainer.isHidden = false
      otpContainer.isHidden = true
      primaryButton.isHidden = false

      phoneInputRow.country = selectedCountry
      phoneInputRow.setFormattedText(formatPhoneByCountry(phoneDigits, selectedCountry.code))
      phoneErrorLabel.text = errorMessage
      let ready = phoneDigits.count == selectedCountry.digits && !isSubmitting
      primaryButton.setEnabledState(ready)
      primaryButton.setLoading(isSubmitting)
      _ = phoneInputRow.becomeFirstResponder()
    case .otp:
      phoneContainer.isHidden = true
      otpContainer.isHidden = false
      primaryButton.isHidden = true

      otpPhoneLabel.text = isolatedPhone()
      otpErrorLabel.text = errorMessage
      otpCellsView.setText(otpValue)
      otpCellsView.setEnabled(!isSubmitting)
      renderResendLabel()
      _ = otpCellsView.becomeFirstResponder()
    }
  }

  private func renderResendLabel() {
    if cooldown > 0 {
      resendLabel.text = String(format: LoginCopy.resendCodeAfter, formatTimer(cooldown))
      resendLabel.textColor = DarbColors.foreground
    } else {
      resendLabel.text = LoginCopy.resendCode
      resendLabel.textColor = DarbColors.primary
    }
  }

  private func isolatedPhone() -> String {
    // Wrap in LRI / PDI so the leading "+" stays on the left even on RTL OSes.
    "\u{2066}\(selectedCountry.code)\(phoneDigits)\u{2069}"
  }

  // MARK: - Actions

  private func pickCountry() {
    // `.alert` style (not `.actionSheet`) because action sheets are unreliable
    // inside the PassKit auth extension's hosting environment — they
    // occasionally fail to present without error. The alert form always works.
    let picker = UIAlertController(title: "Country", message: nil, preferredStyle: .alert)
    for country in LOGIN_COUNTRIES {
      picker.addAction(UIAlertAction(title: "\(country.flag)  \(country.code)", style: .default) { [weak self] _ in
        guard let self else { return }
        self.selectedCountry = country
        self.phoneDigits = ""
        self.errorMessage = nil
        self.render()
      })
    }
    picker.addAction(UIAlertAction(title: "Cancel", style: .cancel))
    present(picker, animated: true)
  }

  private func phoneChanged() {
    let raw = phoneInputRow.rawDigits
    phoneDigits = String(raw.prefix(selectedCountry.digits))
    if errorMessage != nil { errorMessage = nil }
    // Reformat the visible value (display "5X XXX XXXX"-style).
    phoneInputRow.setFormattedText(formatPhoneByCountry(phoneDigits, selectedCountry.code))
    let ready = phoneDigits.count == selectedCountry.digits && !isSubmitting
    primaryButton.setEnabledState(ready)
    phoneErrorLabel.text = nil
  }

  private func otpChanged(_ value: String) {
    otpValue = String(value.filter(\.isNumber).prefix(OTP_LENGTH))
    if errorMessage != nil { errorMessage = nil; otpErrorLabel.text = nil }
    if otpValue.count == OTP_LENGTH, !isSubmitting {
      verifyCode()
    }
  }

  @objc private func primaryTapped() {
    sendCode()
  }

  @objc private func backTapped() {
    phase = .phone
    otpValue = ""
    errorMessage = nil
    stopCooldownTimer()
    cooldown = 0
    render()
  }

  @objc private func resendTapped() {
    guard cooldown == 0, phase == .otp, !isSubmitting else { return }
    resendCode()
  }

  /// Phone-pad has no Return key — the input-accessory Done button is the
  /// only way to dismiss the keyboard. On the phone screen, when the entered
  /// number is the right length, Done also submits (per user request: "dismiss
  /// keyboard and submit").
  @objc private func doneTapped() {
    view.endEditing(true)
    if phase == .phone, !isSubmitting, phoneDigits.count == selectedCountry.digits {
      sendCode()
    }
  }

  // MARK: - Flow

  private func sendCode() {
    guard phoneDigits.count == selectedCountry.digits else { return }
    let identifier = "\(selectedCountry.code)\(phoneDigits)"
    setSubmitting(true)
    errorMessage = nil
    phoneErrorLabel.text = nil

    Task {
      do {
        let prepared = try await client.createSignIn(identifier: identifier)
        try await client.prepareFirstFactor(signInId: prepared.signInId, phoneNumberId: prepared.phoneNumberId)
        await MainActor.run {
          self.prepared = prepared
          self.phase = .otp
          self.otpValue = ""
          self.errorMessage = nil
          self.setSubmitting(false)
          self.startCooldownTimer(seconds: 90)
          self.render()
        }
      } catch {
        await self.showError(error, fallback: LoginCopy.failedToSendCode)
      }
    }
  }

  private func verifyCode() {
    guard let prepared, otpValue.count == OTP_LENGTH else { return }
    let code = otpValue
    setSubmitting(true)
    errorMessage = nil
    otpErrorLabel.text = nil

    Task {
      do {
        let sessionId = try await client.attemptFirstFactor(signInId: prepared.signInId, code: code)
        let token = try await client.mintToken(sessionId: sessionId)
        try SharedKeychain.setAuthToken(token.jwt, expiresAt: token.expiresAt)
        os_log("auth UI → token written, reporting .authorized", log: Self.log, type: .default)
        await MainActor.run { self.finish(.authorized) }
      } catch {
        await self.showError(error, fallback: LoginCopy.invalidCode)
      }
    }
  }

  private func resendCode() {
    guard let prepared else { return }
    setSubmitting(true)
    errorMessage = nil
    otpErrorLabel.text = nil

    Task {
      do {
        try await client.prepareFirstFactor(signInId: prepared.signInId, phoneNumberId: prepared.phoneNumberId)
        await MainActor.run {
          self.setSubmitting(false)
          self.startCooldownTimer(seconds: 90)
        }
      } catch {
        await self.showError(error, fallback: LoginCopy.failedToResend)
      }
    }
  }

  // MARK: - Error mapping (mirrors use-login-flow.ts → mapClerkError)

  private func mapClerkError(_ error: Error) -> String? {
    guard case let .api(api?, _) = (error as? ClerkFrontendClient.ClerkError) else { return nil }
    let code = (api.code ?? "").lowercased()
    let msg = (api.message ?? "").lowercased()

    if code.contains("identifier") || code.contains("phone_number")
        || msg.contains("identifier is invalid") || msg.contains("invalid phone") {
      return LoginCopy.invalidPhoneSimple
    }
    if code == "verification_code_rate_limit_exceeded" {
      return LoginCopy.verificationCodeRateLimitExceeded
    }
    if code.contains("code") || msg.contains("code") {
      return LoginCopy.invalidCode
    }
    return nil
  }

  // MARK: - UI helpers

  @MainActor private func showError(_ error: Error, fallback: String) {
    setSubmitting(false)
    let message = mapClerkError(error) ?? fallback
    errorMessage = message
    switch phase {
    case .phone:
      phoneInputRow.hasError = true
      phoneErrorLabel.text = message
    case .otp:
      otpErrorLabel.text = message
      otpValue = ""
      otpCellsView.setText("")
    }
  }

  private func setSubmitting(_ submitting: Bool) {
    isSubmitting = submitting
    if submitting { spinner.startAnimating() } else { spinner.stopAnimating() }
    phoneInputRow.isEnabled = !submitting
    otpCellsView.setEnabled(!submitting)
    primaryButton.setLoading(submitting)
    let ready = phoneDigits.count == selectedCountry.digits && !submitting
    primaryButton.setEnabledState(ready)
  }

  // MARK: - Cooldown timer

  private func startCooldownTimer(seconds: Int) {
    stopCooldownTimer()
    cooldown = seconds
    renderResendLabel()
    cooldownTimer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in
      guard let self else { return }
      self.cooldown = max(0, self.cooldown - 1)
      self.renderResendLabel()
      if self.cooldown == 0 { self.stopCooldownTimer() }
    }
  }

  private func stopCooldownTimer() {
    cooldownTimer?.invalidate()
    cooldownTimer = nil
  }

  // MARK: - Completion

  private func finish(_ result: PKIssuerProvisioningExtensionAuthorizationResult) {
    guard !didComplete else { return }
    didComplete = true
    stopCooldownTimer()
    completionHandler?(result)
  }
}

// MARK: - Constants / formatters (ported from darbpay-mobile/lib/auth/login)

fileprivate let OTP_LENGTH = 6

fileprivate struct Country {
  let code: String
  let flag: String
  let digits: Int
  let placeholder: String
}

fileprivate let LOGIN_COUNTRIES: [Country] = [
  Country(code: "+966", flag: "🇸🇦", digits: 9, placeholder: "5X XXX XXXX"),
  Country(code: "+1", flag: "🇺🇸", digits: 10, placeholder: "XXX XXX XXXX"),
  Country(code: "+31", flag: "🇳🇱", digits: 9, placeholder: "6 XXXX XXXX"),
  Country(code: "+33", flag: "🇫🇷", digits: 9, placeholder: "X XX XX XX XX"),
]

/// Port of `formatters.ts → formatPhoneByCountry`. Inserts spaces so the
/// visible value reads naturally (`"50 123 4567"`, `"555 123 4567"`).
fileprivate func formatPhoneByCountry(_ digits: String, _ code: String) -> String {
  if code == "+1" {
    if digits.count <= 3 { return digits }
    if digits.count <= 6 { return "\(digits.prefix(3)) \(digits.dropFirst(3))" }
    let p1 = digits.prefix(3)
    let p2 = digits.dropFirst(3).prefix(3)
    let p3 = digits.dropFirst(6).prefix(4)
    return "\(p1) \(p2) \(p3)"
  }
  if digits.count <= 2 { return digits }
  if digits.count <= 5 { return "\(digits.prefix(2)) \(digits.dropFirst(2))" }
  let p1 = digits.prefix(2)
  let p2 = digits.dropFirst(2).prefix(3)
  let p3 = digits.dropFirst(5).prefix(4)
  return "\(p1) \(p2) \(p3)"
}

/// Port of `formatters.ts → formatTimer`. `90 → "01:30"`.
fileprivate func formatTimer(_ seconds: Int) -> String {
  String(format: "%02d:%02d", seconds / 60, seconds % 60)
}

