// MARK: - DarbLogoView

/// Renders the Darb wordmark from the Figma vector (two filled bezier paths,
/// viewBox 60.6667×56). Drawn directly in `draw(_:)` so the extension doesn't
/// need to ship a resource bundle. Scales aspect-fit into any frame.
@available(iOS 14.0, *)
fileprivate final class DarbLogoView: UIView {
  override init(frame: CGRect) {
    super.init(frame: frame)
    backgroundColor = .clear
    isOpaque = false
    contentMode = .redraw
  }
  required init?(coder: NSCoder) { fatalError("init(coder:) not supported") }

  override var intrinsicContentSize: CGSize { CGSize(width: 120, height: 48) }

  override func draw(_ rect: CGRect) {
    guard let ctx = UIGraphicsGetCurrentContext() else { return }
    let viewBox = CGSize(width: 60.6667, height: 56)
    let scale = min(rect.width / viewBox.width, rect.height / viewBox.height)
    let drawnSize = CGSize(width: viewBox.width * scale, height: viewBox.height * scale)
    ctx.saveGState()
    defer { ctx.restoreGState() }
    ctx.translateBy(x: (rect.width - drawnSize.width) / 2, y: (rect.height - drawnSize.height) / 2)
    ctx.scaleBy(x: scale, y: scale)

    DarbColors.primary.setFill()

    let p1 = UIBezierPath()
    p1.move(to: CGPoint(x: 55.1431, y: 21.7787))
    p1.addCurve(to: CGPoint(x: 46.2201, y: 16.5388),
                controlPoint1: CGPoint(x: 52.664, y: 19.2876),
                controlPoint2: CGPoint(x: 49.5792, y: 17.4771))
    p1.addLine(to: CGPoint(x: 44.7463, y: 16.1281))
    p1.addLine(to: CGPoint(x: 45.1252, y: 17.6179))
    p1.addCurve(to: CGPoint(x: 40.6562, y: 34.0301),
                controlPoint1: CGPoint(x: 46.6139, y: 23.4754),
                controlPoint2: CGPoint(x: 44.9014, y: 29.7615))
    p1.addCurve(to: CGPoint(x: 14.2332, y: 52.5677),
                controlPoint1: CGPoint(x: 32.9772, y: 41.7461),
                controlPoint2: CGPoint(x: 24.087, y: 47.9842))
    p1.addLine(to: CGPoint(x: 13.4516, y: 52.9304))
    p1.addLine(to: CGPoint(x: 14.7643, y: 56))
    p1.addLine(to: CGPoint(x: 47.7744, y: 56))
    p1.addLine(to: CGPoint(x: 55.149, y: 48.5898))
    p1.addCurve(to: CGPoint(x: 55.149, y: 21.7787),
                controlPoint1: CGPoint(x: 62.5058, y: 41.1975),
                controlPoint2: CGPoint(x: 62.5058, y: 29.1709))
    p1.close()
    p1.fill()

    let p2 = UIBezierPath()
    p2.move(to: CGPoint(x: 44.4152, y: 14.6773))
    p2.addCurve(to: CGPoint(x: 39.4808, y: 5.97808),
                controlPoint1: CGPoint(x: 43.5799, y: 11.3918),
                controlPoint2: CGPoint(x: 41.8734, y: 8.3822))
    p2.addCurve(to: CGPoint(x: 10.707, y: 5.97808),
                controlPoint1: CGPoint(x: 31.5483, y: -1.99269),
                controlPoint2: CGPoint(x: 18.6396, y: -1.99269))
    p2.addLine(to: CGPoint(x: 0, y: 16.7397))
    p2.addLine(to: CGPoint(x: 13.5262, y: 30.3311))
    p2.addLine(to: CGPoint(x: 15.4534, y: 30.3311))
    p2.addLine(to: CGPoint(x: 25.1969, y: 20.5407))
    p2.addCurve(to: CGPoint(x: 43.3174, y: 15.7594),
                controlPoint1: CGPoint(x: 29.9224, y: 15.7894),
                controlPoint2: CGPoint(x: 36.8675, y: 13.9578))
    p2.addLine(to: CGPoint(x: 44.7911, y: 16.1701))
    p2.addLine(to: CGPoint(x: 44.4122, y: 14.6803))
    p2.close()
    p2.fill()
  }
}

