// MARK: - PhoneInputRow

/// Country chip (tap to pick) + phone field, joined inside a single 14pt-radius
/// bordered container. Stores raw digits separately from the formatted display
/// so the caller can re-format on each change without fighting the cursor.
@available(iOS 14.0, *)
fileprivate final class PhoneInputRow: UIView, UITextFieldDelegate {
  fileprivate var country: Country? {
    didSet { updateCountry() }
  }

  /// Raw digits the user has typed (no spaces). `setFormattedText` is the
  /// inverse — the controller pushes the formatted display value back here.
  var rawDigits: String { (field.text ?? "").filter(\.isNumber) }

  var hasError: Bool = false { didSet { updateBorder() } }
  var isEnabled: Bool {
    get { field.isEnabled }
    set {
      field.isEnabled = newValue
      countryChip.isUserInteractionEnabled = newValue
      alpha = newValue ? 1 : 0.6
    }
  }

  private let onCountryTap: () -> Void
  private let onTextChange: () -> Void

  // UIButton (not bare UIView + tap gesture) so taps register reliably inside
  // the PassKit extension's hosting environment.
  private let countryChip: UIButton = {
    let b = UIButton(type: .custom)
    b.backgroundColor = .clear
    return b
  }()

  private let countryLabel: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 16, weight: .medium)
    l.textColor = DarbColors.foreground
    return l
  }()

  private let chevron: UIImageView = {
    let cfg = UIImage.SymbolConfiguration(pointSize: 12, weight: .semibold)
    let iv = UIImageView(image: UIImage(systemName: "chevron.down", withConfiguration: cfg))
    iv.tintColor = DarbColors.mutedForeground
    iv.contentMode = .scaleAspectFit
    return iv
  }()

  private let divider: UIView = {
    let v = UIView()
    v.backgroundColor = DarbColors.borderLight
    return v
  }()

  private let field: UITextField = {
    let f = UITextField()
    f.font = .systemFont(ofSize: 16, weight: .regular)
    f.textColor = DarbColors.foreground
    f.keyboardType = .phonePad
    f.textContentType = .telephoneNumber
    f.borderStyle = .none
    return f
  }()

  private let container: UIView = {
    let v = UIView()
    v.backgroundColor = DarbColors.background
    v.layer.cornerRadius = 14
    v.layer.borderWidth = 1
    return v
  }()

  init(onCountryTap: @escaping () -> Void, onTextChange: @escaping () -> Void) {
    self.onCountryTap = onCountryTap
    self.onTextChange = onTextChange
    super.init(frame: .zero)

    field.addTarget(self, action: #selector(textChanged), for: .editingChanged)
    field.addTarget(self, action: #selector(focusChanged), for: .editingDidBegin)
    field.addTarget(self, action: #selector(focusChanged), for: .editingDidEnd)
    field.delegate = self

    countryChip.addTarget(self, action: #selector(countryTapped), for: .touchUpInside)

    container.translatesAutoresizingMaskIntoConstraints = false
    countryChip.translatesAutoresizingMaskIntoConstraints = false
    countryLabel.translatesAutoresizingMaskIntoConstraints = false
    chevron.translatesAutoresizingMaskIntoConstraints = false
    divider.translatesAutoresizingMaskIntoConstraints = false
    field.translatesAutoresizingMaskIntoConstraints = false

    addSubview(container)
    container.addSubview(countryChip)
    countryChip.addSubview(countryLabel)
    countryChip.addSubview(chevron)
    container.addSubview(divider)
    container.addSubview(field)

    countryChip.setContentHuggingPriority(.required, for: .horizontal)
    countryChip.setContentCompressionResistancePriority(.required, for: .horizontal)
    field.setContentHuggingPriority(.defaultLow, for: .horizontal)
    field.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)

    NSLayoutConstraint.activate([
      container.topAnchor.constraint(equalTo: topAnchor),
      container.leadingAnchor.constraint(equalTo: leadingAnchor),
      container.trailingAnchor.constraint(equalTo: trailingAnchor),
      container.bottomAnchor.constraint(equalTo: bottomAnchor),
      container.heightAnchor.constraint(equalToConstant: 52),

      // Country chip is explicitly capped at ~28% of the row so the phone
      // field gets the rest of the width. Without this, the chip drifted to
      // ~50% on device even with content-hugging set — UIView has no
      // intrinsic content size, so chevron+label can float arbitrarily.
      countryChip.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: 12),
      countryChip.topAnchor.constraint(equalTo: container.topAnchor),
      countryChip.bottomAnchor.constraint(equalTo: container.bottomAnchor),
      countryChip.widthAnchor.constraint(equalTo: container.widthAnchor, multiplier: 0.28),

      countryLabel.leadingAnchor.constraint(equalTo: countryChip.leadingAnchor),
      countryLabel.centerYAnchor.constraint(equalTo: countryChip.centerYAnchor),

      chevron.leadingAnchor.constraint(equalTo: countryLabel.trailingAnchor, constant: 6),
      chevron.centerYAnchor.constraint(equalTo: countryChip.centerYAnchor),
      chevron.widthAnchor.constraint(equalToConstant: 12),
      chevron.heightAnchor.constraint(equalToConstant: 12),
      chevron.trailingAnchor.constraint(lessThanOrEqualTo: countryChip.trailingAnchor),

      divider.leadingAnchor.constraint(equalTo: countryChip.trailingAnchor, constant: 10),
      divider.topAnchor.constraint(equalTo: container.topAnchor, constant: 12),
      divider.bottomAnchor.constraint(equalTo: container.bottomAnchor, constant: -12),
      divider.widthAnchor.constraint(equalToConstant: 1),

      // Field fills the full container height so the tap target is the entire
      // right portion of the row, not just the 21pt baseline of the text.
      field.leadingAnchor.constraint(equalTo: divider.trailingAnchor, constant: 10),
      field.trailingAnchor.constraint(equalTo: container.trailingAnchor, constant: -12),
      field.topAnchor.constraint(equalTo: container.topAnchor),
      field.bottomAnchor.constraint(equalTo: container.bottomAnchor),
    ])

    updateBorder()
  }
  required init?(coder: NSCoder) { fatalError("init(coder:) not supported") }

  override func becomeFirstResponder() -> Bool { field.becomeFirstResponder() }
  @discardableResult override func resignFirstResponder() -> Bool { field.resignFirstResponder() }

  func setInputAccessoryView(_ view: UIView) {
    field.inputAccessoryView = view
  }

  func setFormattedText(_ text: String) {
    if field.text != text { field.text = text }
    refreshPlaceholder()
  }

  private func refreshPlaceholder() {
    guard let country else { return }
    field.attributedPlaceholder = NSAttributedString(
      string: country.placeholder,
      attributes: [.foregroundColor: DarbColors.mutedForeground]
    )
  }

  @objc private func countryTapped() { onCountryTap() }
  @objc private func textChanged() { onTextChange() }
  @objc private func focusChanged() { updateBorder() }

  private func updateCountry() {
    guard let country else { return }
    countryLabel.text = "\(country.flag)  \(country.code)"
    refreshPlaceholder()
  }

  private func updateBorder() {
    if hasError {
      container.layer.borderColor = DarbColors.destructive.cgColor
    } else if field.isFirstResponder {
      container.layer.borderColor = DarbColors.primary.cgColor
    } else {
      container.layer.borderColor = DarbColors.borderLight.cgColor
    }
  }
}

// MARK: - OtpCellsView

/// Row of N rounded OTP cells. A hidden `oneTimeCode` UITextField captures
/// input (so iOS Messages autofill still works); each visible cell mirrors
/// one character of its current value. The cell at the current cursor
/// position takes the focused (2pt primary) border.
@available(iOS 14.0, *)
fileprivate final class OtpCellsView: UIView, UITextFieldDelegate {
  let length: Int
  var onChange: ((String) -> Void)?
  var text: String { hiddenField.text ?? "" }

  private let stack = UIStackView()
  private var cells: [OtpCell] = []
  private let hiddenField = UITextField()

  init(length: Int) {
    self.length = length
    super.init(frame: .zero)

    stack.axis = .horizontal
    stack.spacing = 8
    stack.distribution = .fillEqually
    stack.translatesAutoresizingMaskIntoConstraints = false
    addSubview(stack)

    for _ in 0..<length {
      let cell = OtpCell()
      cells.append(cell)
      stack.addArrangedSubview(cell)
    }

    hiddenField.keyboardType = .numberPad
    hiddenField.textContentType = .oneTimeCode
    hiddenField.tintColor = .clear
    hiddenField.translatesAutoresizingMaskIntoConstraints = false
    hiddenField.alpha = 0.02
    hiddenField.addTarget(self, action: #selector(textChanged), for: .editingChanged)
    hiddenField.addTarget(self, action: #selector(focusChanged), for: .editingDidBegin)
    hiddenField.addTarget(self, action: #selector(focusChanged), for: .editingDidEnd)
    hiddenField.delegate = self
    addSubview(hiddenField)

    addGestureRecognizer(UITapGestureRecognizer(target: self, action: #selector(tapped)))

    NSLayoutConstraint.activate([
      stack.topAnchor.constraint(equalTo: topAnchor),
      stack.bottomAnchor.constraint(equalTo: bottomAnchor),
      stack.leadingAnchor.constraint(equalTo: leadingAnchor),
      stack.trailingAnchor.constraint(equalTo: trailingAnchor),
      heightAnchor.constraint(equalToConstant: 48),
      // Width: 6 cells × 48pt + 5 gaps × 8pt = 328pt
      widthAnchor.constraint(equalToConstant: CGFloat(length) * 48 + CGFloat(length - 1) * 8),
      hiddenField.topAnchor.constraint(equalTo: topAnchor),
      hiddenField.leadingAnchor.constraint(equalTo: leadingAnchor),
      hiddenField.widthAnchor.constraint(equalToConstant: 1),
      hiddenField.heightAnchor.constraint(equalToConstant: 1),
    ])

    updateCells()
  }
  required init?(coder: NSCoder) { fatalError("init(coder:) not supported") }

  override func becomeFirstResponder() -> Bool { hiddenField.becomeFirstResponder() }
  @discardableResult override func resignFirstResponder() -> Bool { hiddenField.resignFirstResponder() }

  func setInputAccessoryView(_ view: UIView) {
    hiddenField.inputAccessoryView = view
  }

  func setText(_ value: String) {
    let trimmed = String(value.filter(\.isNumber).prefix(length))
    if hiddenField.text != trimmed {
      hiddenField.text = trimmed
    }
    updateCells()
  }

  func setEnabled(_ enabled: Bool) {
    hiddenField.isEnabled = enabled
    isUserInteractionEnabled = enabled
    alpha = enabled ? 1 : 0.6
  }

  @objc private func tapped() { _ = hiddenField.becomeFirstResponder() }

  @objc private func textChanged() {
    let trimmed = String((hiddenField.text ?? "").filter(\.isNumber).prefix(length))
    if hiddenField.text != trimmed { hiddenField.text = trimmed }
    updateCells()
    onChange?(trimmed)
  }

  @objc private func focusChanged() { updateCells() }

  private func updateCells() {
    let chars = Array(text)
    let focusIdx = min(chars.count, length - 1)
    for (i, cell) in cells.enumerated() {
      cell.digit = i < chars.count ? String(chars[i]) : nil
      cell.isCellFocused = hiddenField.isFirstResponder && i == focusIdx
    }
  }
}

@available(iOS 14.0, *)
fileprivate final class OtpCell: UIView {
  var digit: String? { didSet { label.text = digit } }
  var isCellFocused: Bool = false { didSet { updateStyle() } }

  private let label: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 18, weight: .semibold)
    l.textColor = DarbColors.foreground
    l.textAlignment = .center
    return l
  }()

  override init(frame: CGRect) {
    super.init(frame: frame)
    layer.cornerRadius = 12
    layer.borderWidth = 1
    layer.borderColor = DarbColors.borderLight.cgColor
    backgroundColor = DarbColors.background
    label.translatesAutoresizingMaskIntoConstraints = false
    addSubview(label)
    NSLayoutConstraint.activate([
      label.centerXAnchor.constraint(equalTo: centerXAnchor),
      label.centerYAnchor.constraint(equalTo: centerYAnchor),
      widthAnchor.constraint(equalToConstant: 48),
      heightAnchor.constraint(equalToConstant: 48),
    ])
  }
  required init?(coder: NSCoder) { fatalError("init(coder:) not supported") }

  private func updateStyle() {
    layer.borderColor = (isCellFocused ? DarbColors.primary : DarbColors.borderLight).cgColor
    layer.borderWidth = isCellFocused ? 2 : 1
  }
}

// MARK: - PillButton (Continue)

/// Full-width fully-rounded pill button. Enabled state is solid `primary`
/// (`#0078FF`) at full opacity; disabled state animates to opacity 0.4 so the
/// user sees the moment their phone number becomes valid.
@available(iOS 14.0, *)
fileprivate final class PillButton: UIControl {
  var title: String = "" {
    didSet { label.text = title }
  }

  private let label: UILabel = {
    let l = UILabel()
    l.font = .systemFont(ofSize: 16, weight: .medium)
    l.textColor = DarbColors.primaryForeground
    l.textAlignment = .center
    return l
  }()

  private let loadingSpinner: UIActivityIndicatorView = {
    let s = UIActivityIndicatorView(style: .medium)
    s.color = DarbColors.primaryForeground
    s.hidesWhenStopped = true
    return s
  }()

  override init(frame: CGRect) {
    super.init(frame: frame)
    backgroundColor = DarbColors.primary
    clipsToBounds = true

    label.translatesAutoresizingMaskIntoConstraints = false
    loadingSpinner.translatesAutoresizingMaskIntoConstraints = false
    addSubview(label)
    addSubview(loadingSpinner)
    label.isUserInteractionEnabled = false
    loadingSpinner.isUserInteractionEnabled = false

    NSLayoutConstraint.activate([
      label.centerXAnchor.constraint(equalTo: centerXAnchor),
      label.centerYAnchor.constraint(equalTo: centerYAnchor),
      loadingSpinner.centerXAnchor.constraint(equalTo: centerXAnchor),
      loadingSpinner.centerYAnchor.constraint(equalTo: centerYAnchor),
    ])

    setEnabledState(false)
  }
  required init?(coder: NSCoder) { fatalError("init(coder:) not supported") }

  override func layoutSubviews() {
    super.layoutSubviews()
    layer.cornerRadius = bounds.height / 2
  }

  func setEnabledState(_ enabled: Bool) {
    isEnabled = enabled
    UIView.animate(withDuration: 0.15) {
      self.alpha = enabled ? 1 : 0.4
    }
  }

  func setLoading(_ loading: Bool) {
    label.isHidden = loading
    if loading {
      loadingSpinner.startAnimating()
    } else {
      loadingSpinner.stopAnimating()
    }
  }

  override var isHighlighted: Bool {
    didSet { alpha = isHighlighted ? 0.85 : (isEnabled ? 1 : 0.4) }
  }
}

